steps=[]
def add(id,title,instruction,pages,verification,record=False,diagram=True):
    steps.append(dict(id=id,title=title,instruction=instruction,source_pdf_pages=pages,source_links=[URL+'#page='+str(p) for p in pages],verification=[verification],record_required=record,diagram_reference_required=diagram,depends_on=[steps[-1]['id']] if steps else [],origin='Original instruction independently authored from exact 2025 OEM manual; bench ordering is an application composition.'))
add('entry','Confirm the lower-engine bench handoff','Confirm the exact stock US 2025 YZ450F engine is cold, fully drained, removed and securely supported. Head, cylinder, piston and cams are already removed and separately indexed; the timing chain is retained. External clutch cable, coolant, exhaust and electrical connections are disconnected. This operation services crankcases, complete crankshaft assembly, gearbox and their required drives. It retains intact water-pump, pressure-relief and starter-motor internals. Resolve faults in those excluded systems before proceeding.',[244,246,266,273],'Identity, drained condition, removed top end and excluded-system condition recorded.',True)
add('generator-cover-out','Remove the generator cover','Record left-cover bolts and lead-holder positions. Remove the eight cover bolts, lift the cover with its stator and position sensor still installed, and retain two dowels. Remove the old gasket. Protect the lead and keep the cover supported without loading its wiring; do not disturb the stator, sensor or sealed grommet.',[235,237],'Cover assembly and hardware indexed; stator mounts remain intact.')
add('rotor-out','Remove the rotor','Hold the illustrated rotor flats while loosening the rotor nut. Remove nut and washer. Use rotor puller 90890-04151 / YM-04151 to release the rotor; retain the Woodruff key. Do not pry against the stator or sealing surface.',[238],'Rotor, key and washer retained without taper damage.')
add('clutch-out','Remove the clutch spring and plate pack','Remove the clutch cover and old gasket. Loosen the six pressure-plate bolts evenly, then remove pressure plate 1, clutch spring, spring retainer and pressure plate 2. Remove pushrod 1 with its bearing/circlip and the ball. Index the two thin end steels, seven thicker steels, eight friction plates and six collars by type and position.',[244,245,248],'Plate/spring stack and release parts indexed.')
add('boss-out','Remove the clutch boss and primary driven gear','Straighten the clutch-boss nut stake. Hold the boss with holder sleeve 90890-04199 / YM-91042 and remove the nut. Remove spacer, washer, sleeve, six absorbers, boss, washer, primary driven gear, collar, idle gear and its washer in the illustrated order. The removed staked nut will not be reused.',[245,248],'All spacers, washers and absorbers retained in order.')
add('right-cover-out','Remove the right cover and filter','Remove the oil filter cover, element and O-ring, and remove the filler cap and O-ring. Remove the ten right-cover bolts, cover, two dowels and gasket. Keep the complete water pump and the right-cover check-ball seat intact. Replace the removed filter, O-rings and cover gasket during closure.',[96,97,246],'Right cover removed; retained water pump/check-ball assemblies protected.')
add('release-out','Clear the clutch release from the case','Remove the push-lever shaft, two release mounting bolts and complete release assembly, then withdraw pushrod 2. Keep the shaft bearings and seals intact for inspection; retain the pushrod washer and discard the removed O-ring. Do not confuse the cable-operated release with a hydraulic release.',[247],'Release and pushrod removed; seal and bearing condition accessible.')
add('shift-out','Remove the external shift mechanism','Remove shift shaft, collar, return spring and roller, then guide/lever and their two pawls, pins and springs. Remove stopper and spring. Turn the segment counterclockwise until it stops before loosening its bolt; do not use an impact wrench. Remove the segment and protect its locating features.',[255,256,257],'Small shift parts and segment indexed.')
add('drive-out','Remove the primary and balancer drives','Flatten the balancer lock-washer tab. Place an aluminum plate between the illustrated drive/driven teeth to hold them while loosening the primary and balancer nuts. Remove primary nut/washer/gear/collar, starter reduction gear, circlip, starter clutch and balancer drive gear; remove balancer nut, old lock washer, driven gear and oil-pump drive gear. Preserve their order and the timing marks. Remove the damper holder, damper and washer for unrestricted case/bearing work.',[260,261,262],'Gear stacks and damper indexed; holding plate removed.')
add('pump-out','Remove and strip the oil pump','Remove the oil-pump assembly. Index outer/inner rotor 1, its dowel and washer/circlip, then remove the pump cover, outer/inner rotor 2, dowel and shaft. Leave the pressure-relief ball, spring and pressed seat installed. Keep both rotor sets and dowels distinct.',[264,265],'Pump parts indexed; pressure-relief internals remain assembled.')
add('chain-out','Remove the lower timing-chain parts','Remove exhaust-side chain guide, guide stopper plate and timing chain. Retain the guide pivot hardware in order. The top-end parts must already be off; do not pull a trapped chain through assembled cams. Inspect chain stiffness and guide wear/damage now. A stiff chain requires camshaft sprockets, chain and crankshaft sprocket renewed as a set; the crank sprocket is supplied with the complete crankshaft. Record this before selecting the crank assembly, and arrange matching cam/sprocket renewal for later top-end closure. Replace a failed guide.',[266,270,274],'Chain/guide condition and matched-set replacement decision recorded before crank selection.',True)
add('cases-open','Separate the crankcases','Identify the nine case bolts by length and location in the diagram. Loosen each one a quarter turn per pass until all are loose, then remove them. Place the left case downward. Use the designated splitting slit and light soft-hammer taps on reinforced bosses to release the joint; do not pry at mating faces or force separation. Lift the right half horizontally, leaving crank and transmission in the left half. Remove dowels and O-ring.',[267,270],'Cases separated without forced mating-face damage.')
add('transmission-out','Remove the transmission','Remove long/short guide bars with all four springs, shift drum and the three forks, keeping their direction and position recorded. Lift main and drive shafts together; if needed lightly tap the drive shaft with a soft hammer. Keep the drive collar in the case until the assembly is clear, then retain it separately.',[276,279],'Both shafts, forks, bars, springs and drum indexed.')
add('crank-out','Remove the balancer and crank assembly','Turn the balancer flat toward the crank and withdraw it. Use crankcase separating tool 90890-04152 / YU-A9642 as illustrated to remove the complete crankshaft assembly. Do not hammer the crank ends or separate the pressed crank assembly.',[273,274],'Complete crankshaft and balancer removed.')
add('case-clean','Clean and inspect the cases and oil routes','Remove oil strainer, its two bolts, old O-ring and the illustrated small gasket. Remove the two oil nozzles, preserving their identities. Clean gasket residue and cases with mild solvent; inspect for cracks and damage. Clear all cleaning solvent and debris and dry the cases before assembly. Clean oil passages with compressed air while controlling debris; never spin bearings with compressed air. Damaged cases require a correctly matched replacement case set and inspection of all fits, outside this retained-case route.',[25,267,270,271],'Clean passages, strainer/nozzles and sound retained cases accepted.',True)
add('bearings','Inspect and renew case bearings as needed','Check each case bearing for roughness, wear or damage. For a failed bearing remove its illustrated retainer and drive it out by the inner race; discard it. Install the exact replacement parallel by pressing only the outer race, oiling the bearing and keeping its marked/size face outward. Follow the individual left/right diagrams: each illustrated bearing seating depth is 0 mm at its own shown datum. Refit crank-bearing retaining screws at 30 N·m with LOCTITE; other illustrated retaining plates at 12 N·m with LOCTITE. Do not invent a preload or drive against balls/rollers.',[7,25,58,268,269,271],'Bearing decisions, individual seating depths and retainer torques recorded.',True)
add('drive-seal','Renew the drive-shaft case seal','Fit the correct new drive-shaft oil seal with lithium-soap-based grease on its lips and the main lip facing the oil chamber. Seat to 0–0.5 mm at the illustrated case datum. Protect the seal lip when its collar is later inserted.',[25,268],'Drive-shaft seal depth measured and recorded.',True)
add('crank-check','Inspect the crankshaft and balancer','Support and slowly rotate the crank as illustrated while measuring runout with a dial gauge: maximum 0.030 mm. Measure assembly width: 61.93–62.00 mm. Inspect the crank sprocket for wear/damage and clear oil passages with compressed air. Failed runout, width or sprocket condition requires replacement of the complete crank assembly. Inspect the balancer for damage. This route does not press apart the connecting-rod assembly or specify a rod-rebuild process.',[274,275],'Runout, width and complete-assembly disposition recorded.',True)
add('gearbox-check','Inspect shafts, gears and shifting parts','Measure both shaft runouts on centers with a dial gauge: maximum 0.08 mm each. Reject pitted, blue, worn gears or chipped/rounded dogs; replace the affected gears. Inspect forks at followers and pawls and check bars on a flat surface; never straighten a bent bar. Rough fork/bar movement requires replacement of the fork and bar together. Replace a worn/damaged drum assembly. Record every retained and replaced part.',[279,280],'Shaft runouts and all gear/fork/bar/drum decisions recorded.',True)
add('gearbox-build','Rebuild the shaft stacks','Use the exact exploded stack and sectional diagrams for every gear, collar, washer and circlip. Main-shaft gear counts are 22/20/21/16 teeth in the illustrated stack; drive-shaft stack uses 26/21/27/25/28 teeth. Apply molybdenum disulfide oil to idler-gear/collar inner and end faces and sliding-gear inner faces, and engine oil where separately illustrated. Use new circlips with the sharp edge away from the adjacent washer/gear and their ends evenly on spline crests; do not overexpand them. Fit the new illustrated drive-shaft O-ring with lithium-soap-based grease. Each gear must move smoothly before installation.',[7,25,276,277,278,280,281],'Exact gear/washer/collar orientations and circlip seating accepted.',True)
add('crank-in','Install the crank and balancer','Grease seal lips with lithium-soap-based grease and apply molybdenum disulfide grease to both the crankshaft and balancer-shaft locations indicated by the arrows in the diagram. Use crank installer pot 90890-01274 / YU-90058, bolt 90890-01275 / YU-90060, M12 adapter 90890-01278 / YU-90063 and spacer 90890-04081 / YM-91044. Hold the rod at TDC and draw the crank into its bearing until fully seated, using the tool rather than hammering. Fit the balancer with its flat toward the crank.',[273,274,275],'Crank fully seated and balancer installed without impact.',True)
add('transmission-in','Install the transmission and forks','Grease the drive-collar seal lip and install its collar without folding the lip. Oil case bearings and install main and drive shafts together into the left case. Install fork 1 marked L onto the fifth wheel gear, fork 3 marked R onto the fourth wheel, and fork 2 marked C onto the third pinion. Oil fork grooves and drum groove/bearing; install the drum in the illustrated orientation.',[281,282],'Correct fork markings, gear engagement and drum position confirmed.',True)
add('shift-bars-in','Fit guide bars and test shifting','Lightly screw the four springs into the ends of their correct long/short guide bars, oil the bars and install them as illustrated. Operate the drum and rotate the shafts to verify all forks, gears and shifting move smoothly. Do not close the case over binding or incomplete engagement.',[282],'Shift/rotation check passed across all selected positions.',True)
add('nozzles-strainer','Restore the oil nozzles and strainer','Install the right-case oil nozzle with its bolt at 10 N·m and LOCTITE. Install the separate left-case threaded oil nozzle at 0.5 N·m. Fit the clean accepted strainer, new illustrated small gasket and new strainer O-ring with lithium-soap-based grease; tighten the two strainer bolts to 10 N·m with LOCTITE.',[7,58,267,271,272],'Nozzles and strainer restored with correct separate preparations.',True)
add('cases-close','Seal and join the cases','Account for all tools, cloths and loose parts. Fit dowels and new illustrated O-ring. Apply ThreeBond 1215 to the mating surface path shown in the diagram, keeping passages clear. Hold the rod at TDC, lower the right case onto the left and seat it with light soft-hammer taps only. Match the nine bolts to the 45/60/75 mm length map. Tighten crisscross to 12 N·m in two stages, quarter-turn increments. Confirm crank and transmission still move freely after tightening.',[267,271,272],'Case bolt map/torque and post-closure free movement recorded.',True)
add('chain-in','Restore the timing chain and guide','Confirm the chain/guide decisions recorded before case splitting were implemented. If stiffness required a matched set, the installed crankshaft must already have the new sprocket and matching cam/sprocket parts must be reserved for top-end closure. Never pair a fresh chain with failed retained sprockets. Install the accepted chain, guide and stopper plate in their illustrated positions. Tighten the guide pivot bolt to 12 N·m and stopper plate bolt to 10 N·m with LOCTITE. Retain the chain securely for the separate top-end installation.',[266,270,274],'Chain/guide decisions and matched-sprocket requirement recorded; guide secured and chain retained.',True)
add('pump-inspect','Inspect the oil-pump parts','Inspect both rotor sets, shaft, cover and housing for cracks, damage or wear. Replace the complete pump if damaged or if it fails smooth movement after correct reassembly. Keep the retained pressure-relief seat/ball/spring undisturbed; a suspected relief fault requires its separate repair before engine use.',[265],'Pump condition and retained relief-system decision recorded.',True)
add('pump-build','Assemble and install the pump','Oil shaft, rotor set 2 and its dowel; engage the dowel with the inner-rotor slit and fit the cover at 6 N·m with LOCTITE. Fit washer, dowel and oiled rotor set 1 with a new circlip, ensuring the pin engages its groove. Install the assembly at 5 N·m with LOCTITE. Verify smooth rotation after each fastening stage; failed movement must be corrected before proceeding.',[25,264,265],'Rotor/dowel engagement, 6/5 N·m and smooth rotation recorded.',True)
add('drives-inspect','Inspect the drive gears and starter clutch','Inspect both primary drive and driven gears: damage or wear of either gear, abnormal primary-gear noise or excessive free play requires replacement of primary drive and driven gears together. Inspect balancer gears separately and replace failed balancer parts. Inspect the starter clutch for burrs, chipped teeth, roughness or wear and replace the complete failed assembly. Fit it with the balancer drive and reduction gear for a functional check: turning the balancer drive counterclockwise must freewheel; clockwise must engage.',[249,262],'Gear dispositions and directional starter-clutch check recorded.',True)
add('balancer-in','Restore the timed balancer drive','Install oil-pump drive gear and balancer driven gear with their lower splines aligned to the shaft. Install balancer drive gear with its lower spline aligned to the crank and align the punched drive/driven timing marks exactly. Fit a new lock washer and tighten the balancer nut to 50 N·m using the aluminum holding plate as illustrated. Bend the locking tab after tightening.',[25,260,263],'Balancer timing marks and 50 N·m locking recorded.',True)
add('primary-in','Restore starter clutch and primary drive','Oil the starter clutch and fit its manufacturer mark outward, then a new circlip, starter reduction gear with oil on its inner/contact faces, collar, primary gear and washer. Apply molybdenum disulfide grease to the washer contact and primary-nut threads/contact surface. With the aluminum plate in the illustrated holding position, tighten the primary nut to 130 N·m. Remove the holding plate. Restore damper, washer and holder with two bolts at 12 N·m and LOCTITE.',[7,25,58,260,261,263],'130 N·m preparation/torque and damper closure recorded.',True)
add('shift-inspect','Inspect the shift mechanism','Reject bent/worn shaft, damaged spring, guide, lever, pawls, pins or springs. Inspect stopper and its spring and replace failed parts. Ensure replacement parts match the original stock configuration.',[257,258],'Shift-mechanism parts accepted.',True)
add('shift-restore','Restore segment and pawls','Install stopper, collar and spring with the stopper bolt at 10 N·m and LOCTITE. Align the segment projections with the drum slits while pressing the stopper down; tighten the segment bolt to 30 N·m with LOCTITE as marked in the exploded diagram. Oil the two pawl springs, pins and pawls; install lever and guide together, then guide bolts at 10 N·m with LOCTITE.',[7,255,258,259],'Segment location, pawls and separate fasteners confirmed.',True)
add('shift-shaft','Restore the shift shaft and seal','Fit the correct new shift-shaft seal with lithium-soap-based grease on its lips, seating depth 0–1 mm at the illustrated datum. Oil the shaft, then fit dowel/roller, return spring and collar in the diagram positions. Confirm return action and shifting while rotating the transmission by hand.',[25,255,259],'Seal depth and shift-return function recorded.',True)
add('release-check','Inspect the clutch release and pushrods','Inspect push-lever shaft, pushrods 1 and 2, bearing and ball for wear, cracks or damage. Check pushrod 2 bending: maximum 0.10 mm. This route retains sound release bearings and seals; failed internal bearings/seals require the separate renewal operation before continuing. Replace damaged pushrods/ball or complete matching release parts as applicable.',[249,250],'Pushrod bending and release condition accepted.',True)
add('release-in','Refit the cable clutch release','Oil the retained shaft bearings and apply lithium-soap-based grease to seal lips. Fit pushrod 2 with its washer and a new O-ring lubricated with lithium-soap-based grease. Restore the complete release with bolts at 10 N·m and LOCTITE, then install the push-lever shaft. Keep the cable disconnected until engine refitting.',[247,250,251],'Release and pushrod installed; cable remains for frame closure.')
add('right-cover-in','Refit the right cover','Inspect the retained right-cover seal/check-ball seat and water-pump assembly for damage before closure; this route does not disturb their internals. Fit two dowels and a new right-cover gasket, align the retained components and install the ten bolts in their original length positions. Tighten in stages crisscross to 10 N·m.',[246,250,251],'Right cover seated with new gasket and intact retained assemblies.')
add('filter-in','Install a new filter','Install the correct new filter element in the illustrated orientation and a new filter-cover O-ring lubricated with lithium-soap-based grease. Refit the filter cover and tighten both bolts to 10 N·m. Fit the filler cap with a new O-ring lubricated with lithium-soap-based grease to protect the engine; fluid filling belongs to the later engine-refit operation. Record that this engine was disassembled and the filter renewed.',[96,97,246],'New filter and O-ring installed; cover 10 N·m and disassembly condition recorded.',True)
add('clutch-inspect','Inspect clutch friction and release parts','Measure each friction plate at four places: standard 2.12–2.28 mm, limit 2.02 mm; replace the friction set if failed. Check every steel plate on a flat surface with a feeler gauge: warpage maximum 0.10 mm; replace the steel set if failed. Measure clutch spring free height: standard 5.80 mm, minimum 5.51 mm. Replace damaged retainer/pressure plates; replace the collar set if worn/pitted. Inspect boss/driven dogs, sleeves and absorbers and replace damaged parts rather than inventing a material-removal allowance.',[248,249],'Friction/steel/spring measurements and replacement decisions recorded.',True)
add('clutch-base','Restore the clutch base stack','Fit washer, idle gear, collar, primary driven gear, washer, boss, six absorbers, sleeve, washer and spacer in the exact diagram order. Oil the mainshaft, specified washer faces, collar inner face, driven-gear inner/contact surfaces, absorber surfaces, sleeve inner/contact face and spacer faces. Do not trap the washer on the spacer step.',[251,252],'All washers, spacers and absorbers correctly located.')
add('clutch-nut','Secure the clutch boss','Apply LOCTITE to the correct new boss nut and tighten to 105 N·m using holder sleeve 90890-04199 / YM-91042. Check that the washer rotates freely, then stake the nut into the mainshaft cutouts. The neighboring oiled spacer/washer stack does not change the nut locking-agent instruction.',[7,58,244,245,252],'105 N·m, free washer and stake recorded.',True)
add('clutch-pack','Build the plate pack','Oil six collars, all friction plates and steel plates. Follow the exact pack diagram: the two 1.0 mm steels are the two extreme end plates, the seven 1.4 mm steels alternate internally with eight frictions. The four blue-marked friction plates form two at each end of the friction sequence; the four unmarked frictions occupy its center. Preserve the illustrated pawl/paint orientation and do not interchange the thin end steels with internal steels.',[245,252,253],'Exact end plates and painted/unpainted friction sequence confirmed.',True)
add('pressure-plate','Install the release ball and clutch spring','Oil the bearing and fit a new circlip on pushrod 1; oil the ball and rod and install them. Fit pressure plate 2, spring retainer, clutch spring in the engine-side orientation shown, then pressure plate 1. Oil the six bolt threads/contact surfaces and the illustrated pressure-plate contact. Tighten every bolt crisscross to 4 N·m first, then every bolt crisscross to 10 N·m.',[25,253,254],'Spring orientation and 4 then 10 N·m stages recorded.',True)
add('clutch-cover','Close the clutch','Install a new clutch-cover gasket and restore the two long/four short bolts according to the diagram. Tighten in stages crisscross to 10 N·m. Keep external cable adjustment for the engine-refit operation.',[244,254],'Clutch cover sealed and fastened.')
add('rotor-check','Inspect and install the rotor','Inspect rotor inner surface and stator outer surface for damage; damage requires crank runout/bearing assessment before reuse. Replace a damaged key. Clean both crank and rotor tapers. Fit the Woodruff key with its flat parallel to the crank centerline, align the rotor keyway and seat the rotor. Fit washer and nut and hold the illustrated flats to tighten the nut to 65 N·m.',[238,239],'Tapers, key alignment and 65 N·m recorded.',True)
add('generator-cover-in','Close the generator','Confirm stator/sensor mounts and lead grommet remained intact. Fit two dowels and a new gasket, then cover and lead holder in recorded positions. Tighten eight bolts in stages crisscross to 10 N·m. Fit the oil-tank drain with a new gasket at 10 N·m and crankcase drain with a new gasket at 20 N·m if they were left out after draining.',[97,235,239],'Generator cover and both drained-oil closures secured.')
add('exit','Record the lower-engine handoff','Record installed crank/gear/bearing/clutch/pump parts, all measurements, gear and balancer timing, torque preparations, seal depths, free movement and new filter. Keep the timing chain supported and cylinder opening clean. This engine remains without its top end and oil fill: complete the exact 2025 top-end assembly, engine refit, oil/coolant restoration and commissioning before any start. Disassembled oil quantity is 1.20 L, subject to the later verified level/flow checks; do not start a dry bench engine.',[97,266,272,282],'Lower bench work accepted; top-end/refit/commissioning still outstanding.',True)
pages=sorted({p for s in steps for p in s['source_pdf_pages']})
def printed(p):
    if p==7:return 'Symbols (unnumbered)'
    if p==25:return '1-13'
    if p==58:return '2-11'
    if p in [96,97]:return '3-'+str(p-82)
    return '5-'+str(p-199)
