data=dict(schema_version=1,id='yamaha-2025-yz450f-lower-engine-bench-v1',target=target,scope_confirmed=True,title='Rebuild the stock lower engine on the bench',status='SOURCE_REVIEWED_BOUNDED_PROCEDURE',publication_status='PENDING_INDEPENDENT_REVIEW',source=dict(source_url=URL,document_sha256=SHA,document_revision='D02-2819U-10 / LIT-11626-38-16; First edition March 2024',pdf_pages=pages,printed_pages=[printed(p) for p in pages],review_status='PENDING_INDEPENDENT_REVIEW',review_note='Exact 2025 text and rendered diagrams reviewed, including independent 2025 clutch nut preparation. No 2026 numerical inheritance.'),completeness='Continuous lower-bench candidate including required clutch/generator/shift/pump drives, case bearings, complete crank assembly and gearbox inspection/replacement. Not an assembled-bike guide or pressed connecting-rod rebuild.',applicability=dict(included='Exact standard US 2025 YZ450F stock lower engine with sound retained cases.',excluded=['Pressed connecting-rod/crank assembly internal rebuilding','Water-pump, starter-motor, pressure-relief valve and stator electrical internal rebuilding','Failed retained clutch-release internal seals/bearings','Damaged case-set replacement or machining','Top-end teardown/reassembly, engine-frame installation, fluid filling and running'],year_inheritance='NONE'),affected_components=['engine','crankshaft','transmission','clutch','oil_pump'],entry_state=['Engine removed, drained, cold and securely supported.','Top end and piston removed; all parts indexed; external interfaces disconnected.'],exit_state=['Cases, lower drives, clutch and side covers closed; gearbox and crank move freely.','Top end remains removed; oil fill and engine refitting/commissioning remain outstanding.'],preflight=['Arrange exact top-end access and later closure before starting.','Have the cited gear-stack, case-bearing, fastener-length, timing and clutch-spring diagrams available.','Resolve suspected failures in excluded retained assemblies before teardown.','Have correct stock replacement parts, new seals/gaskets/circlips/staked nut/lock washer and calibrated tools.'],required_tools=[dict(name=x) for x in ['Secure engine fixture, parts trays and chain-retaining wire','Calibrated torque tools spanning 0.5–130 N·m; hand sockets and illustrated holding spanner','Rotor puller 90890-04151 / YM-04151; clutch holder sleeve 90890-04199 / YM-91042','Crank separator 90890-04152 / YU-A9642; crank installer pot01274/bolt01275/M12adapter01278/spacer04081 with listed equivalents in the step','Bearing drivers/press, depth gauge, soft hammer and aluminum holding plate','Dial gauge and shaft supports/centers; micrometer, flat plate, feeler gauge and caliper','Controlled compressed air, mild cleaning solvent and clean trays']],required_parts=[dict(name=x) for x in ['Measured accepted stock parts or exact replacement complete crank assembly, gears/forks/bars/bearings/pump/clutch parts','New case/cover gaskets, case/strainer/drive/release O-rings and shaft seals','New circlips, balancer lock washer and clutch boss nut','New oil filter and cover/filler O-rings; new drain gaskets','Engine oil, molybdenum disulfide oil, molybdenum disulfide grease, lithium-soap-based grease','ThreeBond 1215; LOCTITE locking agent at specifically cited joints (OEM does not identify a grade here)']],critical_stop_conditions=['Damaged retained cases or excluded assembly requiring an unprovided repair.','Failed measured fit, gear engagement or crank/shaft movement.','Missing washer/circlip, foreign material, ambiguous diagram orientation or forced assembly.'],operation_dependencies=[],steps=steps)
